test.config:
indexer
{
	mem_limit = 16M
}

searchd
{

}

source e1_source
{
	type = mysql

	sql_query = SELECT id, title, body, gid FROM e1_docs ORDER BY id
	sql_attr_uint = gid
}

index e1_plain
{
	source = e1_source
	path = /e1_plain
	index_field_lengths = 1
}

index norms_plain
{
	source = e1_source
	path = /norms_plain
}

index e1_rt
{
	type = rt
	path = /e1_rt
	rt_field = title
	rt_field = body
	rt_attr_uint = gid
}

index e1_ties
{
	type = rt
	path = /e1_ties
	rt_field = body
}

index e1_direct_rt
{
	type = rt
	path = /e1_direct_rt
	rt_field = title
	rt_field = body
	rt_attr_uint = gid
}

index e1_attrs_only
{
	type = rt
	path = /e1_attrs_only
	rt_attr_uint = gid
}

index e1_merge2
{
	type = rt
	path = /e1_merge2
	rt_field = body
}

index e1_merge_n
{
	type = rt
	path = /e1_merge_n
	rt_field = body
}

queries.sphinxql:
INSERT INTO e1_rt (id,title,body,gid) VALUES
(1,'alpha alpha beta','gamma',1),
(2,'alpha','alpha alpha gamma',1),
(3,'beta gamma','alpha',2);
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=bm25a;
SELECT id,weight() AS w FROM e1_rt WHERE MATCH('alpha') ORDER BY w DESC,id ASC OPTION ranker=expr('1000*bm25a(1.2,0.75,256)+0');
FLUSH RAMCHUNK e1_rt;
INSERT INTO e1_rt (id,title,body,gid) VALUES
(4,'alpha beta','beta alpha',2),
(5,'gamma','beta',3),
(6,'alpha alpha alpha','alpha beta gamma',3);
FLUSH RAMCHUNK e1_rt;
INSERT INTO e1_ties (id,body) VALUES (30,'tie'),(20,'tie'),(10,'tie');
